mapper.select:
SELECT ac.seqno ,AC.BUSI_DATE busiDate,AC.END_TIME, (case when IFNULL(LOG.ERROR,0) = 0 then '02' else '09' end) STATUS , CASE WHEN LOG.TMP_NAME in ('ftp-download','sftp-download') THEN CASE WHEN IFNULL(LOG.ERROR,0)!=0 AND IFNULL(LOG.SUCCESS,0)=0 THEN '文件不存�?' WHEN IFNULL(LOG.ERROR,0) =0 AND IFNULL(LOG.SUCCESS,0)!=0 then '下载成功' END ELSE (case when IFNULL ( LOG.ERROR, 0 ) = 0 then concat_ws('','执行成功' ,LOG.success , '条') else concat_ws('','执行成功' , IFNULL ( LOG.success, 0 ), '条,失败' , IFNULL ( LOG.ERROR, 0 ), '条') end) END detailAction
,IFNULL(GR.TASK_GRP_NAME,LOG.FILE_NAME) taskCname,
log.TMP_NAME eName,ac.START_TIME startTime FROM ( SELECT TMP_NAME,FILE_NAME,PARENT_SEQNO, (case when IS_CHECK = 'Y' then COUNT(1) else 0 end) SUCCESS, (case when IS_CHECK = 'N' then COUNT(1) else 0 end) ERROR FROM VAL_INTERFLOG GROUP BY TMP_NAME,FILE_NAME,PARENT_SEQNO,IS_CHECK )LOG left join ( SELECT TASK_GRP_ID, TASK_GRP_NAME FROM bok_BATCH_TASK_GRP GROUP BY TASK_GRP_ID, TASK_GRP_NAME ) GR on GR.TASK_GRP_ID = LOG.TMP_NAME LEFT JOIN VAL_INTERF_ACTIONLOG AC ON AC.SEQNO=LOG.PARENT_SEQNO WHERE AC.SEQNO = #{seqno}

select SEQNO,busiDate,startTime,endTime,status,detailAction,taskCname,lastTime,orderno from ( SELECT LOG.SEQNO,DATE_FORMAT(LOG.BUSI_DATE,'%Y%m%d') busiDate,LOG.START_TIME startTime,LOG.END_TIME endTime ,(case when LOG.STATUS = '02' then (case when IFNULL( logDetail.ERROR, 0 ) = 0 then '02' else '09' end) else LOG.STATUS end) STATUS ,(case when LOG.STATUS = '02' then (case when ifnull ( logDetail.ERROR, 0 ) = 0 then concat_ws('','执行成功' , IFNULL ( logDetail.success, 0 ), '条') else concat_ws('','执行成功' , IFNULL ( logDetail.success, 0 ), '条,失败' , IFNULL ( logDetail.ERROR, 0 ), '条' ) end) else LOG.DETAIL_ACTION end) detailAction ,GR.TASK_GRP_NAME taskCname,ROUND(LOG.LAST_TIME/1000,2) lastTime,GR.orderno FROM VAL_INTERF_ACTIONLOG LOG left join ( SELECT TASK_GRP_ID, TASK_GRP_NAME,ORDER_NO orderno FROM bok_BATCH_TASK_GRP GROUP BY TASK_GRP_ID, TASK_GRP_NAME,ORDER_NO ) GR on GR.TASK_GRP_ID = DATE_FORMAT(LOG.ORDERNO) LEFT JOIN( SELECT a.parent_seqno,sum(a.success) success,sum(a.ERROR) ERROR FROM ( SELECT parent_seqno parent_seqno, (case when VAL.IS_CHECK = 'Y' then LENGHT end) success, (case when VAL.IS_CHECK = 'N' then LENGHT end) ERROR from ( SELECT parent_seqno,IS_CHECK,COUNT(1) LENGHT FROM VAL_INTERFLOG WHERE 1=1 group by parent_seqno,IS_CHECK) val) a group by parent_seqno
) logDetail ON LOG.Seqno=logDetail.parent_seqno WHERE 1=1
AND LOG.EXECTASK_SEQNO = #{execTaskId} ) logdetail WHERE 1=1
AND logdetail.status = #{status}
ORDER BY busiDate,logdetail.orderno
